"""The steps themselves. Each takes text and returns text."""


class Step:
    """One transformation."""

    def apply(self, text: str) -> str:
        raise NotImplementedError


class Upper(Step):
    def apply(self, text: str) -> str:
        return text.upper()


class Strip(Step):
    def apply(self, text: str) -> str:
        return text.strip()


class Squeeze(Step):
    def apply(self, text: str) -> str:
        return " ".join(text.split())


class Truncate(Step):
    def __init__(self, length: int):
        self._length = length

    def apply(self, text: str) -> str:
        return text[: self._length]

"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        base, arg = name.split(":", 1)
        if base not in STEPS:
            raise KeyError(f"no step named {base!r}. Known: {', '.join(sorted(STEPS))}")
        step_cls = STEPS[base]
        if isinstance(step_cls, Truncate):
            if arg == "":
                raise ValueError("truncate length is missing")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(f"truncate length is not a number: {arg!r}")
            return Truncate(length)
        raise ValueError(f"{base!r} does not take arguments")
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

import pytest
from pipeline.runner import run_pipeline


def test_upper():
    assert run_pipeline("abc", ["upper"]) == "ABC"


def test_chain():
    assert run_pipeline("  a   b  ", ["strip", "squeeze"]) == "a b"


def test_unknown_step():
    with pytest.raises(KeyError):
        run_pipeline("x", ["nope"])


# Truncate tests

def test_truncate_basic():
    assert run_pipeline("abcdef", ["truncate:3"]) == "abc"


def test_truncate_past_end():
    assert run_pipeline("abc", ["truncate:99"]) == "abc"


def test_truncate_zero():
    assert run_pipeline("abc", ["truncate:0"]) == ""


def test_truncate_missing_length():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:"])


def test_truncate_non_numeric():
    with pytest.raises(ValueError):
        run_pipeline("abc", ["truncate:abc"])


def test_truncate_no_colon():
    with pytest.raises(KeyError):
        run_pipeline("abc", ["truncate"])


def test_truncate_with_strip():
    assert run_pipeline("  hello world  ", ["strip", "truncate:5"]) == "hello"

